ruleContent.content:
@js:
(function(){
  var html=String(result||'');
  var kind='';
  try{kind=String(book.getVariable('joy_kind')||'');}catch(e){}
  if(!kind){
    var m=html.match(/href="https?:\/\/joyacg\.top\/(comic|anime)\/"[^>]*class="badge bg-primary/);
    if(m)kind=m[1];
  }
  if(kind=='anime'){
    try{book.type=4;}catch(e){}
    try{
      var doc=org.jsoup.Jsoup.parse(html);
      var v=doc.select('#content video[data-encoded-src]').first();
      if(v){
        var enc=String(v.attr('data-encoded-src')||'');
        if(enc){
          var u=String(java.base64Decode(enc));
          if(u.indexOf('http')===0)return u;
        }
      }
      var v2=doc.select('#content video[src]').first();
      if(v2)return String(v2.attr('src'));
    }catch(e){}
    return '未找到播放地址，若需登录/付费，请点击书源登录按钮跳转网页登录：https://joyacg.top/auth/';
  }
  var out=[];
  try{book.type=64;book.imageStyle='FULL';}catch(e){}
  try{
    var doc=org.jsoup.Jsoup.parse(html);
    var imgs=doc.select('#content img[data-src]');
    for(var i=0;i<imgs.size();i++){
      var u=String(imgs.get(i).attr('data-src')||'');
      u=u.replace(/^https?:\/\/i[01]\.wp\.com\//,'');
      if(u.indexOf('//')===0)u='https:'+u;
      if(u.indexOf('http')!==0)u='https://'+u;
      if(u.indexOf('http')===0)out.push('<img src="'+u+'">');
    }
    if(out.length===0){
      var imgs2=doc.select('#content img[src]');
      for(var j=0;j<imgs2.size();j++){
        var u2=String(imgs2.get(j).attr('src')||'');
        u2=u2.replace(/^https?:\/\/i[01]\.wp\.com\//,'');
        if(u2.indexOf('//')===0)u2='https:'+u2;
        if(u2.indexOf('http')!==0)u2='https://'+u2;
        if(u2.indexOf('http')===0)out.push('<img src="'+u2+'">');
      }
    }
  }catch(e){
    var re=/<img[^>]+data-src="([^"]+)"/g;
    var mm;
    while((mm=re.exec(html))!==null){
      var u3=mm[1].replace(/^https?:\/\/i[01]\.wp\.com\//,'');
      if(u3.indexOf('//')===0)u3='https:'+u3;
      if(u3.indexOf('http')!==0)u3='https://'+u3;
      if(u3.indexOf('http')===0)out.push('<img src="'+u3+'">');
    }
  }
  if(out.length===0)return '未获取到图片，可能需登录：https://joyacg.top/auth/';
  return out.join('\n');
})()

