function setMode(mode,name){
  try{source.put('joy_mode',mode);}catch(e){}
  try{source.put('searchType',name);}catch(e){}
  java.longToast('已切换：'+name+'，请刷新发现小宝宝 🥰');
  try{java.refreshExplore();}catch(e){}
}
var st=source.get('joy_mode');
if(st==null||st==''){st='all';source.put('joy_mode',st);}
function openWebLogin(){
  try{
    java.startBrowserAwait('https://joyacg.top/auth/','请在网页中登录，登录完成后返回阅读刷新即可');
  }catch(e){
    try{java.openUrl('https://joyacg.top/auth/');}catch(e2){java.toast('请手动打开 https://joyacg.top/auth/ 登录');}
  }
}
function showState(){
  var s=source.get('joy_mode')||'all';
  var n=s=='anime'?'动漫':(s=='comic'?'漫画':'全部');
  java.toast('当前模式：'+n+'，搜索/发现按此分类进行');
}
